INSERT INTO `smf_personalized_bbc` VALUES
(2,'audio','Play audio.','<audio src=\"$1\" controls preload=\"none\"></audio>','personalizedBBC/audio','<audio src=\"','\" controls preload=\"none\"></audio>',0,0,0,0,1,1,1,'rfc0'),
(3,'bgcolor','Changes the background color.','<span class=\"bgcolor\" data-bgcolor=\"$2\">$1</span>','personalizedBBC/bgcolor','<span class=\"bgcolor\" data-bgcolor=\"$1\">','</span>',1,0,1,0,1,1,1,'rfc0'),
(5,'hover','Give text on hover.','<span class=\"preview\" style=\"border-bottom: 1px dashed gray;\" title=\"$2\">$1</span>','personalizedBBC/hover','<span class=\"preview\" style=\"border-bottom: 1px dashed gray;\" title=\"$1\">','</span>',1,0,1,0,1,1,1,'rfc0'),
(6,'spoilertxt','In-line spoiler.','<span class=\"spoilertxt\">$1</span>','personalizedBBC/spoilertxt','<span class=\"spoilertxt\">','</span>',1,0,0,0,1,1,1,'rfc0'),
(7,'valign','Change vertical alignment of an image.','<span class=\"vertical-align-$2\">$1</span>','personalizedBBC/valign','<span class=\"vertical-align-$1\">','</span>',1,0,1,0,1,1,1,'rfc0'),
(8,'video','Plays a non-youtube video,','<div class=\"video\"><video style=\"max-height:500px; width:auto;\" src=\"$1\" controls crossorigin=\"anonymous\" preload=\"metadata\"></video></div>','personalizedBBC/video','','',0,0,0,0,1,1,1,'rfc0'),
(9,'glow','Makes text glow.','<span class=\"glow\" data-color=\"$2\">$1</span>','personalizedBBC/glow','<span class=\"glow\" data-color=\"$1\">','</span>',1,0,1,0,1,1,1,'rfc0'),
(10,'inlinecode','Inline code','<code>$1</code>','personalizedBBC/inlinecode','','',0,0,0,0,1,1,1,'rfc0'),
(11,'columns','A simpler way to define tables.','<table><tr><td>$1</td></tr></table>','personalizedBBC/table','<table><tr><td>','</td></tr></table>',1,0,0,1,1,1,1,'rfc0'),
(12,'nextcol','Create the next column in a [columns] tag.','</td><td>','personalizedBBC/nextcol','','',0,0,3,0,1,1,1,'rfc0'),
(13,'nextrow','Create a new row in a [columns] tag.','</td></tr><tr><td>','personalizedBBC/nextrow','','',0,0,3,0,1,1,1,'rfc0'),
(17,'souptable','Soups up your table. For when you want a souped up table.','<div class=\"souped-up-table\">$1</div>','personalizedBBC/souptable','<div class=\"souped-up-table\">','</div>',1,0,0,1,1,1,1,'rfc0'),
(18,'h2','Level 2 header','<h2>$1</h2>','personalizedBBC/no_image','<h2>','</h2>',1,0,0,0,1,0,1,'rfc0'),
(19,'tamanotchi','Legacy tag for tamanotchi embeds from the old DUMB','<img src=\"https://tamanotchi.world/includes/scripts/img2.php?id=$2.PNG&size=$1\">','personalizedBBC/no_image','','',0,0,1,0,1,0,1,'rfc0'),
(20,'utxtbox','Undertale-style text box','<div class=\"utxtbox\">$1</div>','personalizedBBC/uttxtbox','<div class=\"utxtbox\">','</div>',1,1,0,0,1,1,1,'rfc0'),
(21,'txtbox','Deltarune-style text box','<div class=\"txtbox\">$1</div>','personalizedBBC/txtbox','<div class=\"txtbox\">','</div>',1,1,0,0,1,1,1,'rfc0'),
(22,'fixedwidthsig','Makes a signature exactly 800px wide on all layouts.','<div style=\"white-space: nowrap; width: 800px;\">$1</div>','personalizedBBC/no_image','<div style=\"white-space: nowrap; width: 800px;\">','</div>',2,0,0,1,1,0,1,'rfc0'),
(23,'align','Legacy tag from Jcink.','<div align=\"$2\">$1</div>','personalizedBBC/no_image','<div align=\"$1\">','</div>',1,0,1,1,1,0,1,'rfc0');
